import torch
import torch.nn as nn
import networkx as nx
import numpy as np

# --- Encoder-decoder structure for news content and neighborhood encoding ---
class HetTransformerEncoder(nn.Module):
    def __init__(self, content_dim, neighborhood_dim, hidden_dim, num_heads):
        super(HetTransformerEncoder, self).__init__()
        self.content_projection = nn.Linear(content_dim, hidden_dim)
        self.neighborhood_projection = nn.Linear(neighborhood_dim, hidden_dim)
        self.multihead_attn = nn.MultiheadAttention(hidden_dim, num_heads)

    def forward(self, content_embeddings, neighborhood_embeddings):
        content_embeddings = self.content_projection(content_embeddings)
        neighborhood_embeddings = self.neighborhood_projection(neighborhood_embeddings)
        combined_embeddings = torch.cat((content_embeddings, neighborhood_embeddings), dim=-1)
        attn_output, _ = self.multihead_attn(combined_embeddings, combined_embeddings, combined_embeddings)
        return attn_output

class HetTransformerDecoder(nn.Module):
    def __init__(self, hidden_dim, output_dim):
        super(HetTransformerDecoder, self).__init__()
        self.linear = nn.Linear(hidden_dim, output_dim)

    def forward(self, encoder_output):
        logits = self.linear(encoder_output)
        return logits

# --- Heterogeneous neighbor sampling and RWR-based strategies ---
class RWRNeighborSampler:
    def __init__(self, graph, restart_prob=0.1):
        self.graph = graph
        self.restart_prob = restart_prob

    def sample(self, node_id, walk_length):
        current_node = node_id
        path = [current_node]

        for _ in range(walk_length - 1):
            neighbors = list(self.graph.neighbors(current_node))
            if not neighbors:
                break

            # Choose the next node with RWR probability
            if np.random.rand() < self.restart_prob:
                current_node = np.random.choice(list(self.graph.nodes()))
            else:
                current_node = np.random.choice(neighbors)

            path.append(current_node)

        return path

# --- Type-specific transformation matrices ---
class TypeSpecificProjection(nn.Module):
    def __init__(self, node_types, input_dim, output_dim):
        super(TypeSpecificProjection, self).__init__()
        self.projection_matrices = nn.ParameterList([
            nn.Linear(input_dim, output_dim) for _ in range(len(node_types))
        ])

    def forward(self, embeddings, node_types):
        transformed_embeddings = []
        for i, embedding in enumerate(embeddings):
            node_type = node_types[i]
            projection_matrix = self.projection_matrices[node_type]
            transformed_embedding = projection_matrix(embedding)
            transformed_embeddings.append(transformed_embedding)
        return torch.stack(transformed_embeddings)

# --- Multi-modal semantic aggregation ---
def aggregate_multi_modal_semantics(content_embeddings, neighborhood_embeddings, multihead_attn):
    combined_embeddings = torch.cat((content_embeddings, neighborhood_embeddings), dim=-1)
    attn_output, _ = multihead_attn(combined_embeddings, combined_embeddings, combined_embeddings)
    return attn_output
